macro_rules! Float {
    () => {
        deps!();
        # [doc = " A self-contained host- and target-independent arbitrary-precision"] # [doc = " floating-point software implementation."] # [doc = ""] # [doc = " `apfloat` uses significand bignum integer arithmetic as provided by functions"] # [doc = " in the `ieee::sig`."] # [doc = ""] # [doc = " Written for clarity rather than speed, in particular with a view to use in"] # [doc = " the front-end of a cross compiler so that target arithmetic can be correctly"] # [doc = " performed on the host. Performance should nonetheless be reasonable,"] # [doc = " particularly for its intended use. It may be useful as a base"] # [doc = " implementation for a run-time library during development of a faster"] # [doc = " target-specific one."] # [doc = ""] # [doc = " All 5 rounding modes in the IEEE-754R draft are handled correctly for all"] # [doc = " implemented operations. Currently implemented operations are add, subtract,"] # [doc = " multiply, divide, fused-multiply-add, conversion-to-float,"] # [doc = " conversion-to-integer and conversion-from-integer. New rounding modes"] # [doc = " (e.g. away from zero) can be added with three or four lines of code."] # [doc = ""] # [doc = " Four formats are built-in: IEEE single precision, double precision,"] # [doc = " quadruple precision, and x87 80-bit extended double (when operating with"] # [doc = " full extended precision). Adding a new format that obeys IEEE semantics"] # [doc = " only requires adding two lines of code: a declaration and definition of the"] # [doc = " format."] # [doc = ""] # [doc = " All operations return the status of that operation as an exception bit-mask,"] # [doc = " so multiple operations can be done consecutively with their results or-ed"] # [doc = " together. The returned status can be useful for compiler diagnostics; e.g.,"] # [doc = " inexact, underflow and overflow can be easily diagnosed on constant folding,"] # [doc = " and compiler optimizers can determine what exceptions would be raised by"] # [doc = " folding operations and optimize, or perhaps not optimize, accordingly."] # [doc = ""] # [doc = " At present, underflow tininess is detected after rounding; it should be"] # [doc = " straight forward to add support for the before-rounding case too."] # [doc = ""] # [doc = " The library reads hexadecimal floating point numbers as per C99, and"] # [doc = " correctly rounds if necessary according to the specified rounding mode."] # [doc = " Syntax is required to have been validated by the caller."] # [doc = ""] # [doc = " It also reads decimal floating point numbers and correctly rounds according"] # [doc = " to the specified rounding mode."] # [doc = ""] # [doc = " Non-zero finite numbers are represented internally as a sign bit, a 16-bit"] # [doc = " signed exponent, and the significand as an array of integer limbs. After"] # [doc = " normalization of a number of precision P the exponent is within the range of"] # [doc = " the format, and if the number is not denormal the P-th bit of the"] # [doc = " significand is set as an explicit integer bit. For denormals the most"] # [doc = " significant bit is shifted right so that the exponent is maintained at the"] # [doc = " format's minimum, so that the smallest denormal has just the least"] # [doc = " significant bit of the significand set. The sign of zeros and infinities"] # [doc = " is significant; the exponent and significand of such numbers is not stored,"] # [doc = " but has a known implicit (deterministic) value: 0 for the significands, 0"] # [doc = " for zero exponent, all 1 bits for infinity exponent. For NaNs the sign and"] # [doc = " significand are deterministic, although not really meaningful, and preserved"] # [doc = " in non-conversion operations. The exponent is implicitly all 1 bits."] # [doc = ""] # [doc = " `apfloat` does not provide any exception handling beyond default exception"] # [doc = " handling. We represent Signaling NaNs via IEEE-754R 2008 6.2.1 should clause"] # [doc = " by encoding Signaling NaNs with the first bit of its trailing significand as"] # [doc = " 0."] # [doc = ""] # [doc = " Future work"] # [doc = " ==========="] # [doc = ""] # [doc = " Some features that may or may not be worth adding:"] # [doc = ""] # [doc = " Optional ability to detect underflow tininess before rounding."] # [doc = ""] # [doc = " New formats: x87 in single and double precision mode (IEEE apart from"] # [doc = " extended exponent range) (hard)."] # [doc = ""] # [doc = " New operations: sqrt, nexttoward."] # [doc = ""] pub trait Float : Copy + Default + FromStr < Err = ParseError > + PartialOrd + fmt :: Display + Neg < Output = Self > + AddAssign + SubAssign + MulAssign + DivAssign + RemAssign + Add < Output = StatusAnd < Self > > + Sub < Output = StatusAnd < Self > > + Mul < Output = StatusAnd < Self > > + Div < Output = StatusAnd < Self > > + Rem < Output = StatusAnd < Self > > { # [doc = " Total number of bits in the in-memory format."] const BITS : usize ; # [doc = " Number of bits in the significand. This includes the integer bit."] const PRECISION : usize ; # [doc = " The largest E such that 2^E is representable; this matches the"] # [doc = " definition of IEEE 754."] const MAX_EXP : ExpInt ; # [doc = " The smallest E such that 2^E is a normalized number; this"] # [doc = " matches the definition of IEEE 754."] const MIN_EXP : ExpInt ; # [doc = " Positive Zero."] const ZERO : Self ; # [doc = " Positive Infinity."] const INFINITY : Self ; # [doc = " NaN (Not a Number)."] const NAN : Self ; # [doc = " Factory for QNaN values."] fn qnan (payload : Option < u128 >) -> Self ; # [doc = " Factory for SNaN values."] fn snan (payload : Option < u128 >) -> Self ; # [doc = " Largest finite number."] fn largest () -> Self ; # [doc = " Smallest (by magnitude) finite number."] # [doc = " Might be denormalized, which implies a relative loss of precision."] const SMALLEST : Self ; # [doc = " Smallest (by magnitude) normalized finite number."] fn smallest_normalized () -> Self ; fn add_r (self , rhs : Self , round : Round) -> StatusAnd < Self > ; fn sub_r (self , rhs : Self , round : Round) -> StatusAnd < Self > { self . add_r (- rhs , round) } fn mul_r (self , rhs : Self , round : Round) -> StatusAnd < Self > ; fn mul_add_r (self , multiplicand : Self , addend : Self , round : Round) -> StatusAnd < Self > ; fn mul_add (self , multiplicand : Self , addend : Self) -> StatusAnd < Self > { self . mul_add_r (multiplicand , addend , Round :: NearestTiesToEven) } fn div_r (self , rhs : Self , round : Round) -> StatusAnd < Self > ; # [doc = " IEEE remainder."] fn ieee_rem (self , rhs : Self) -> StatusAnd < Self > ; # [doc = " C fmod, or llvm frem."] fn c_fmod (self , rhs : Self) -> StatusAnd < Self > ; fn round_to_integral (self , round : Round) -> StatusAnd < Self > ; # [doc = " IEEE-754R 2008 5.3.1: nextUp."] fn next_up (self) -> StatusAnd < Self > ; # [doc = " IEEE-754R 2008 5.3.1: nextDown."] # [doc = ""] # [doc = " *NOTE* since nextDown(x) = -nextUp(-x), we only implement nextUp with"] # [doc = " appropriate sign switching before/after the computation."] fn next_down (self) -> StatusAnd < Self > { (- self) . next_up () . map (| r | - r) } fn abs (self) -> Self { if self . is_negative () { - self } else { self } } fn copy_sign (self , rhs : Self) -> Self { if self . is_negative () != rhs . is_negative () { - self } else { self } } fn from_bits (input : u128) -> Self ; fn from_i128_r (input : i128 , round : Round) -> StatusAnd < Self > { if input < 0 { Self :: from_u128_r (input . wrapping_neg () as u128 , - round) . map (| r | - r) } else { Self :: from_u128_r (input as u128 , round) } } fn from_i128 (input : i128) -> StatusAnd < Self > { Self :: from_i128_r (input , Round :: NearestTiesToEven) } fn from_u128_r (input : u128 , round : Round) -> StatusAnd < Self > ; fn from_u128 (input : u128) -> StatusAnd < Self > { Self :: from_u128_r (input , Round :: NearestTiesToEven) } fn from_str_r (s : & str , round : Round) -> Result < StatusAnd < Self > , ParseError > ; fn to_bits (self) -> u128 ; # [doc = " Convert a floating point number to an integer according to the"] # [doc = " rounding mode. In case of an invalid operation exception,"] # [doc = " deterministic values are returned, namely zero for NaNs and the"] # [doc = " minimal or maximal value respectively for underflow or overflow."] # [doc = " If the rounded value is in range but the floating point number is"] # [doc = " not the exact integer, the C standard doesn't require an inexact"] # [doc = " exception to be raised. IEEE-854 does require it so we do that."] # [doc = ""] # [doc = " Note that for conversions to integer type the C standard requires"] # [doc = " round-to-zero to always be used."] # [doc = ""] # [doc = " The *is_exact output tells whether the result is exact, in the sense"] # [doc = " that converting it back to the original floating point type produces"] # [doc = " the original value. This is almost equivalent to result==Status::OK,"] # [doc = " except for negative zeroes."] fn to_i128_r (self , width : usize , round : Round , is_exact : & mut bool) -> StatusAnd < i128 > { let status ; if self . is_negative () { if self . is_zero () { * is_exact = false ; } let r = unpack ! (status =, (- self) . to_u128_r (width , - round , is_exact)) ; if r > (1 << (width - 1)) { * is_exact = false ; Status :: INVALID_OP . and (- 1 << (width - 1)) } else { status . and (r . wrapping_neg () as i128) } } else { self . to_u128_r (width - 1 , round , is_exact) . map (| r | r as i128) } } fn to_i128 (self , width : usize) -> StatusAnd < i128 > { self . to_i128_r (width , Round :: TowardZero , & mut true) } fn to_u128_r (self , width : usize , round : Round , is_exact : & mut bool) -> StatusAnd < u128 > ; fn to_u128 (self , width : usize) -> StatusAnd < u128 > { self . to_u128_r (width , Round :: TowardZero , & mut true) } fn cmp_abs_normal (self , rhs : Self) -> Ordering ; # [doc = " Bitwise comparison for equality (QNaNs compare equal, 0!=-0)."] fn bitwise_eq (self , rhs : Self) -> bool ; # [doc = " Implements IEEE minNum semantics. Returns the smaller of the 2 arguments if"] # [doc = " both are not NaN. If either argument is a NaN, returns the other argument."] fn min (self , other : Self) -> Self { if self . is_nan () { other } else if other . is_nan () { self } else if other < self { other } else { self } } # [doc = " Implements IEEE maxNum semantics. Returns the larger of the 2 arguments if"] # [doc = " both are not NaN. If either argument is a NaN, returns the other argument."] fn max (self , other : Self) -> Self { if self . is_nan () { other } else if other . is_nan () { self } else if self < other { other } else { self } } # [doc = " Implements IEEE 754-2018 minimum semantics. Returns the smaller of 2"] # [doc = " arguments, propagating NaNs and treating -0 as less than +0."] fn minimum (self , other : Self) -> Self { if self . is_nan () { self } else if other . is_nan () { other } else if self . is_zero () && other . is_zero () && self . is_negative () != other . is_negative () { if self . is_negative () { self } else { other } } else if other < self { other } else { self } } # [doc = " Implements IEEE 754-2018 maximum semantics. Returns the larger of 2"] # [doc = " arguments, propagating NaNs and treating -0 as less than +0."] fn maximum (self , other : Self) -> Self { if self . is_nan () { self } else if other . is_nan () { other } else if self . is_zero () && other . is_zero () && self . is_negative () != other . is_negative () { if self . is_negative () { other } else { self } } else if self < other { other } else { self } } # [doc = " IEEE-754R isSignMinus: Returns true if and only if the current value is"] # [doc = " negative."] # [doc = ""] # [doc = " This applies to zeros and NaNs as well."] fn is_negative (self) -> bool ; # [doc = " IEEE-754R isNormal: Returns true if and only if the current value is normal."] # [doc = ""] # [doc = " This implies that the current value of the float is not zero, subnormal,"] # [doc = " infinite, or NaN following the definition of normality from IEEE-754R."] fn is_normal (self) -> bool { ! self . is_denormal () && self . is_finite_non_zero () } # [doc = " Returns true if and only if the current value is zero, subnormal, or"] # [doc = " normal."] # [doc = ""] # [doc = " This means that the value is not infinite or NaN."] fn is_finite (self) -> bool { ! self . is_nan () && ! self . is_infinite () } # [doc = " Returns true if and only if the float is plus or minus zero."] fn is_zero (self) -> bool { self . category () == Category :: Zero } # [doc = " IEEE-754R isSubnormal(): Returns true if and only if the float is a"] # [doc = " denormal."] fn is_denormal (self) -> bool ; # [doc = " IEEE-754R isInfinite(): Returns true if and only if the float is infinity."] fn is_infinite (self) -> bool { self . category () == Category :: Infinity } # [doc = " Returns true if and only if the float is a quiet or signaling NaN."] fn is_nan (self) -> bool { self . category () == Category :: NaN } # [doc = " Returns true if and only if the float is a signaling NaN."] fn is_signaling (self) -> bool ; fn category (self) -> Category ; fn is_non_zero (self) -> bool { ! self . is_zero () } fn is_finite_non_zero (self) -> bool { self . is_finite () && ! self . is_zero () } fn is_pos_zero (self) -> bool { self . is_zero () && ! self . is_negative () } fn is_neg_zero (self) -> bool { self . is_zero () && self . is_negative () } fn is_pos_infinity (self) -> bool { self . is_infinite () && ! self . is_negative () } fn is_neg_infinity (self) -> bool { self . is_infinite () && self . is_negative () } # [doc = " Returns true if and only if the number has the smallest possible non-zero"] # [doc = " magnitude in the current semantics."] fn is_smallest (self) -> bool { Self :: SMALLEST . copy_sign (self) . bitwise_eq (self) } # [doc = " Returns true if this is the smallest (by magnitude) normalized finite"] # [doc = " number in the given semantics."] fn is_smallest_normalized (self) -> bool { Self :: smallest_normalized () . copy_sign (self) . bitwise_eq (self) } # [doc = " Returns true if and only if the number has the largest possible finite"] # [doc = " magnitude in the current semantics."] fn is_largest (self) -> bool { Self :: largest () . copy_sign (self) . bitwise_eq (self) } # [doc = " Returns true if and only if the number is an exact integer."] fn is_integer (self) -> bool { if ! self . is_finite () { return false ; } self . round_to_integral (Round :: TowardZero) . value . bitwise_eq (self) } # [doc = " If this value has an exact multiplicative inverse, return it."] fn get_exact_inverse (self) -> Option < Self > ; # [doc = " Returns the exponent of the internal representation of the Float."] # [doc = ""] # [doc = " Because the radix of Float is 2, this is equivalent to floor(log2(x))."] # [doc = " For special Float values, this returns special error codes:"] # [doc = ""] # [doc = "   NaN -> \\c IEK_NAN"] # [doc = "   0   -> \\c IEK_ZERO"] # [doc = "   Inf -> \\c IEK_INF"] # [doc = ""] fn ilogb (self) -> ExpInt ; # [doc = " Returns: self * 2^exp for integral exponents."] fn scalbn_r (self , exp : ExpInt , round : Round) -> Self ; fn scalbn (self , exp : ExpInt) -> Self { self . scalbn_r (exp , Round :: NearestTiesToEven) } # [doc = " Equivalent of C standard library function."] # [doc = ""] # [doc = " While the C standard says exp is an unspecified value for infinity and nan,"] # [doc = " this returns INT_MAX for infinities, and INT_MIN for NaNs (see `ilogb`)."] fn frexp_r (self , exp : & mut ExpInt , round : Round) -> Self ; fn frexp (self , exp : & mut ExpInt) -> Self { self . frexp_r (exp , Round :: NearestTiesToEven) } }
    };
}

